using System;

namespace Game_Catalog.Models
{
    /// <summary> Represents a goal the player set for a game. </summary>
    public class Goal
    {
        /// <summary> Unique identifier of the goal. Generated by the database. </summary>
        public int GoalId { get; set; }

        /// <summary> Identifier of the game the goal belongs to. </summary>
        public int GameId { get; set; }

        private string _gameTitle = string.Empty;

        /// <summary> Title of the game, loaded together with the goal. </summary>
        public string GameTitle
        {
            get => _gameTitle;
            set => _gameTitle = value ?? string.Empty;
        }

        private string _goalName = string.Empty;

        /// <summary> Short name of the goal. </summary>
        public string GoalName
        {
            get => _goalName;
            set => _goalName = value ?? string.Empty;
        }

        private string _goalDescription = string.Empty;

        /// <summary> Free-form description. Empty means no description. </summary>
        public string GoalDescription
        {
            get => _goalDescription;
            set => _goalDescription = value ?? string.Empty;
        }

        /// <summary> Status shown to the player. Computed by the database; changed only through the repository actions. </summary>
        public GoalStatus Status { get; set; } = GoalStatus.Active;

        /// <summary> Priority from 1 (highest) to 5 (lowest). </summary>
        public int Priority { get; set; } = 3;

        /// <summary> Date and time the goal was created. Set by the database. </summary>
        public DateTime CreatedAt { get; set; }

        /// <summary> Planned completion date. Null means no deadline. </summary>
        public DateTime? DueDate { get; set; }

        /// <summary> Date and time the goal was completed. Null unless the goal is completed. </summary>
        public DateTime? CompletedAt { get; set; }

        /// <summary> Days left until the due date, never below zero. Computed by the database for active goals with a due date. </summary>
        public int? DaysLeft { get; set; }

        /// <summary> Full days from creation to completion. Computed by the database for completed goals. </summary>
        public int? CompletionDays { get; set; }
    }
}